// CSV export/import of books.
import { addBook } from "./store.mjs";

const COLUMNS = ["id", "title", "author", "year", "tags", "copies"];

const quote = (v) => {
  const s = String(v);
  return /[",\n\r]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
};

export function exportBooks(store) {
  const lines = [COLUMNS.join(",")];
  for (const b of store.books) {
    lines.push([b.id, b.title, b.author, b.year, b.tags.join(";"), b.copies].map(quote).join(","));
  }
  return lines.join("\n") + "\n";
}

// Returns [{ line, fields }] where line is the 1-based line the record starts on.
function parseRecords(text) {
  const records = [];
  let fields = [];
  let field = "";
  let inQuotes = false;
  let line = 1;
  let start = 1;
  let touched = false;
  const endRecord = () => {
    fields.push(field);
    records.push({ line: start, fields });
    fields = [];
    field = "";
    touched = false;
  };
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (inQuotes) {
      if (c === '"') {
        if (text[i + 1] === '"') { field += '"'; i++; } else inQuotes = false;
      } else {
        if (c === "\n") line++;
        field += c;
      }
      continue;
    }
    if (c === '"') { inQuotes = true; touched = true; }
    else if (c === ",") { fields.push(field); field = ""; touched = true; }
    else if (c === "\r" && text[i + 1] === "\n") continue;
    else if (c === "\n") {
      if (touched || field !== "" || fields.length) endRecord();
      line++;
      start = line;
    } else { field += c; touched = true; }
  }
  if (touched || field !== "" || fields.length) endRecord();
  return records;
}

const isWhole = (s) => /^-?\d+$/.test(s);

export function importBooks(store, text) {
  const records = parseRecords(text);
  const errors = [];
  let added = 0;
  if (!records.length) return { added, errors };
  const header = records[0].fields.map((h) => h.trim());
  const idx = Object.fromEntries(header.map((h, i) => [h, i]));
  const get = (f, name) => (idx[name] === undefined ? "" : (f[idx[name]] ?? "").trim());
  for (const { line, fields } of records.slice(1)) {
    const title = get(fields, "title");
    const author = get(fields, "author");
    const year = get(fields, "year");
    const tags = get(fields, "tags");
    const copies = get(fields, "copies");
    let message = null;
    if (!title) message = "title is required";
    else if (!author) message = "author is required";
    else if (!isWhole(year)) message = "year must be a whole number";
    else if (copies !== "" && !(isWhole(copies) && Number(copies) > 0)) message = "copies must be a positive whole number";
    if (message) { errors.push({ line, message }); continue; }
    addBook(store, {
      title,
      author,
      year: Number(year),
      tags: tags === "" ? [] : tags.split(";"),
      copies: copies === "" ? 1 : Number(copies),
    });
    added++;
  }
  return { added, errors };
}
